(function(){'use strict';
const Z=[
{id:'SBH01',n:'Kota Kinabalu',d:'Ibu negeri - Land Below The Wind!',o:0},
{id:'SBH02',n:'Papar',d:'Kawasan barat daya Sabah',o:1},
{id:'SBH03',n:'Sandakan',d:'Wildlife capital - Sepilok, Kinabatangan',o:2},
{id:'SBH04',n:'Semporna',d:'Sipadan #1 diving dunia!',o:3},
{id:'SBH05',n:'Labuan',d:'Offshore oil &amp; gas 50-150km laut',o:4},
{id:'SBH06',n:'Mt Kinabalu',d:'4,095m - berbuka paling lewat 15-20 min!',o:16},
{id:'SBH07',n:'Kudat',d:'Tip of Borneo',o:5}
];
const B=[
{d:'Khamis',r:1,dt:'19 Feb',im:'05:15',bk:'18:52'},
{d:'Jumaat',r:2,dt:'20 Feb',im:'05:15',bk:'18:52'},
{d:'Sabtu',r:3,dt:'21 Feb',im:'05:15',bk:'18:52'},
{d:'Ahad',r:4,dt:'22 Feb',im:'05:15',bk:'18:52'},
{d:'Isnin',r:5,dt:'23 Feb',im:'05:15',bk:'18:51'},
{d:'Selasa',r:6,dt:'24 Feb',im:'05:15',bk:'18:51'},
{d:'Rabu',r:7,dt:'25 Feb',im:'05:14',bk:'18:51'},
{d:'Khamis',r:8,dt:'26 Feb',im:'05:14',bk:'18:51'},
{d:'Jumaat',r:9,dt:'27 Feb',im:'05:14',bk:'18:51'},
{d:'Sabtu',r:10,dt:'28 Feb',im:'05:14',bk:'18:50'},
{d:'Ahad',r:11,dt:'1 Mac',im:'05:14',bk:'18:50'},
{d:'Isnin',r:12,dt:'2 Mac',im:'05:14',bk:'18:50'},
{d:'Selasa',r:13,dt:'3 Mac',im:'05:13',bk:'18:50'},
{d:'Rabu',r:14,dt:'4 Mac',im:'05:13',bk:'18:49'},
{d:'Khamis',r:15,dt:'5 Mac',im:'05:13',bk:'18:49'},
{d:'Jumaat',r:16,dt:'6 Mac',im:'05:13',bk:'18:49'},
{d:'Sabtu',r:17,dt:'7 Mac',im:'05:13',bk:'18:49'},
{d:'Ahad',r:18,dt:'8 Mac',im:'05:12',bk:'18:48'},
{d:'Isnin',r:19,dt:'9 Mac',im:'05:12',bk:'18:48'},
{d:'Selasa',r:20,dt:'10 Mac',im:'05:12',bk:'18:48'},
{d:'Rabu',r:21,dt:'11 Mac',im:'05:12',bk:'18:48'},
{d:'Khamis',r:22,dt:'12 Mac',im:'05:11',bk:'18:47'},
{d:'Jumaat',r:23,dt:'13 Mac',im:'05:11',bk:'18:47'},
{d:'Sabtu',r:24,dt:'14 Mac',im:'05:11',bk:'18:47'},
{d:'Ahad',r:25,dt:'15 Mac',im:'05:11',bk:'18:47'},
{d:'Isnin',r:26,dt:'16 Mac',im:'05:10',bk:'18:46'},
{d:'Selasa',r:27,dt:'17 Mac',im:'05:10',bk:'18:46'},
{d:'Rabu',r:28,dt:'18 Mac',im:'05:10',bk:'18:46'},
{d:'Khamis',r:29,dt:'19 Mac',im:'05:10',bk:'18:46'},
{d:'Jumaat',r:30,dt:'20 Mac',im:'05:09',bk:'18:45'}
];
let cz=0,ct=null;
function am(t,m){const p=t.split(':');let h=parseInt(p[0]),mn=parseInt(p[1]);mn+=m;if(mn>=60){h+=Math.floor(mn/60);mn%=60;}if(mn<0){h--;mn+=60;}return String(h).padStart(2,'0')+':'+String(mn).padStart(2,'0');}
function gd(zi){const o=Z[zi].o;return B.map(r=>({...r,im:am(r.im,-Math.floor(o*0.4)),bk:am(r.bk,o)}));}
function rt(){
const tb=document.getElementById('ilmxSbhTbody'),data=gd(cz),today=new Date();
document.getElementById('ilmxSbhTh2').textContent='Imsak '+Z[cz].id;
document.getElementById('ilmxSbhTH2').textContent='Berbuka '+Z[cz].id;
let h='';
data.forEach((r,i)=>{const d=new Date(2026,1,19+i),isT=d.toDateString()===today.toDateString();h+=`<tr${isT?' class="today"':''}><td>${r.d}</td><td>${r.r} Ramadan</td><td>${r.dt} 2026</td><td class="tc">${r.im}</td><td class="tc">${r.bk}</td></tr>`;});
tb.innerHTML=h;
}
function uc(){
const today=new Date(),rs=new Date(2026,1,19),diff=Math.floor((today-rs)/864e5);
if(diff<0||diff>=30){document.getElementById('ilmxSbhToday').innerHTML='<strong>Ramadan 2026 bermula 19 Feb!</strong>';ct=null;return;}
const data=gd(cz),row=data[diff],bp=row.bk.split(':');
ct=new Date(today.getFullYear(),today.getMonth(),today.getDate(),parseInt(bp[0]),parseInt(bp[1]),0);
document.getElementById('ilmxSbhToday').innerHTML='<strong>Hari ini ('+row.r+' Ramadan) - '+Z[cz].id+':</strong> Imsak '+row.im+' | Berbuka '+row.bk;
}
function tick(){
if(!ct)return;
const d=ct-new Date();
if(d<0){document.getElementById('ilmxSbhH').textContent=document.getElementById('ilmxSbhM').textContent=document.getElementById('ilmxSbhS').textContent='00';return;}
document.getElementById('ilmxSbhH').textContent=String(Math.floor(d/36e5)).padStart(2,'0');
document.getElementById('ilmxSbhM').textContent=String(Math.floor(d%36e5/6e4)).padStart(2,'0');
document.getElementById('ilmxSbhS').textContent=String(Math.floor(d%6e4/1e3)).padStart(2,'0');
}
window.ilmxSbh=function(idx){
cz=idx;
document.querySelectorAll('.ilmx-sbh-zone-btn').forEach((b,i)=>b.classList.toggle('active',i===idx));
const z=Z[idx];
document.getElementById('ilmxSbhZN').textContent=z.id+' '+z.n;
document.getElementById('ilmxSbhInfo').innerHTML='✅ <strong>'+z.id+':</strong> '+z.d;
rt();uc();
};
document.addEventListener('DOMContentLoaded',()=>{rt();uc();setInterval(tick,1000);});
})();
